using System.IdentityModel.Tokens.Jwt;
using System.Net;
using System.Net.Http.Json;
using System.Security.Claims;
using System.Text;
using Benchmark.Api;
using Microsoft.IdentityModel.Tokens;
using Xunit;
namespace Benchmark.Tests;
public sealed class HttpTests
{
    [Fact] public async Task Public_health_stays_healthy() {using var s=new ApiFixture();using var c=s.CreateClient();Assert.Equal(HttpStatusCode.OK,(await c.GetAsync("/health")).StatusCode);}
    [Fact] public async Task Unknown_route_remains_404() {using var s=new ApiFixture();using var c=s.CreateClient();Assert.Equal(HttpStatusCode.NotFound,(await c.GetAsync("/missing")).StatusCode);}
    [Fact] public async Task Login_issues_signed_issuer_audience_scoped_expiring_JWT() {using var s=new ApiFixture();using var c=await s.Login();var h=new JwtSecurityTokenHandler{MapInboundClaims=false};var p=h.ValidateToken(c.DefaultRequestHeaders.Authorization!.Parameter!,new TokenValidationParameters{ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(ApiFixture.Key)),ValidateIssuer=true,ValidIssuer=ApiFixture.Issuer,ValidateAudience=true,ValidAudience=ApiFixture.Audience,ValidateLifetime=true,ClockSkew=TimeSpan.Zero},out var t);Assert.Equal("alice@example.test",p.FindFirst("sub")?.Value);Assert.Equal("User",p.FindFirst(ClaimTypes.Role)?.Value);var jwt=Assert.IsType<JwtSecurityToken>(t);Assert.Equal("HS256",jwt.Header.Alg);Assert.InRange(jwt.ValidTo-DateTime.UtcNow,TimeSpan.FromMinutes(1),TimeSpan.FromMinutes(16));}
    [Fact] public async Task Wrong_password_rejected() {using var s=new ApiFixture();using var c=s.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await c.PostAsJsonAsync("/api/auth/login",new LoginInput("alice@example.test","wrong"))).StatusCode);}
    [Fact] public async Task Unknown_account_rejected() {using var s=new ApiFixture();using var c=s.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await c.PostAsJsonAsync("/api/auth/login",new LoginInput("unknown@example.test","Alice!234"))).StatusCode);}
    [Fact] public async Task Empty_credentials_invalid() {using var s=new ApiFixture();using var c=s.CreateClient();Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsJsonAsync("/api/auth/login",new LoginInput("",""))).StatusCode);}
    [Fact] public async Task Anonymous_list_rejected() {using var s=new ApiFixture();using var c=s.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/work-items")).StatusCode);}
    [Fact] public async Task Anonymous_create_rejected() {using var s=new ApiFixture();using var c=s.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await c.PostAsJsonAsync("/api/work-items",new CreateInput("A"))).StatusCode);}
    [Fact] public async Task Anonymous_update_rejected() {using var s=new ApiFixture();using var c=s.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await c.PutAsJsonAsync($"/api/work-items/{Guid.NewGuid()}",new UpdateInput("A","Todo",1))).StatusCode);}
    [Fact] public async Task Anonymous_delete_rejected() {using var s=new ApiFixture();using var c=s.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await c.DeleteAsync($"/api/work-items/{Guid.NewGuid()}?expectedVersion=1")).StatusCode);}
    [Fact] public async Task Malformed_token_rejected() {using var s=new ApiFixture();using var c=s.CreateClient();c.DefaultRequestHeaders.Authorization=new("Bearer","wrong.jwt");Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/work-items")).StatusCode);}
    [Fact] public async Task Invalid_signature_rejected() {using var s=new ApiFixture();using var c=s.CreateClient();c.DefaultRequestHeaders.Authorization=new("Bearer",ApiFixture.Token(key:new string('x',64)));Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/work-items")).StatusCode);}
    [Fact] public async Task Wrong_issuer_rejected() {using var s=new ApiFixture();using var c=s.CreateClient();c.DefaultRequestHeaders.Authorization=new("Bearer",ApiFixture.Token(issuer:"wrong"));Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/work-items")).StatusCode);}
    [Fact] public async Task Wrong_audience_rejected() {using var s=new ApiFixture();using var c=s.CreateClient();c.DefaultRequestHeaders.Authorization=new("Bearer",ApiFixture.Token(audience:"wrong"));Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/work-items")).StatusCode);}
    [Fact] public async Task Expired_token_rejected() {using var s=new ApiFixture();using var c=s.CreateClient();c.DefaultRequestHeaders.Authorization=new("Bearer",ApiFixture.Token(expiredMinutes:-10));Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/work-items")).StatusCode);}
    [Fact] public async Task Admin_login_is_valid_but_remains_private() {using var s=new ApiFixture();using var alice=await s.Login();await ApiFixture.Add(alice);using var admin=await s.Login("admin@example.test","Admin!234");var jwt=new JwtSecurityTokenHandler().ReadJwtToken(admin.DefaultRequestHeaders.Authorization!.Parameter!);Assert.Equal("Admin",jwt.Claims.FirstOrDefault(claim=>claim.Type==ClaimTypes.Role)?.Value);Assert.Empty((await admin.GetFromJsonAsync<ItemDto[]>("/api/work-items"))!);}
    [Fact] public async Task Create_trims_title_and_starts_at_version_one() {using var s=new ApiFixture();using var c=await s.Login();var r=await c.PostAsJsonAsync("/api/work-items",new CreateInput("  Plan  "));Assert.Equal(HttpStatusCode.Created,r.StatusCode);var t=(await r.Content.ReadFromJsonAsync<ItemDto>())!;Assert.Equal("Plan",t.Title);Assert.Equal("Todo",t.Status);Assert.Equal(1,t.Version);Assert.NotEqual(Guid.Empty,t.Id);Assert.Equal($"/api/work-items/{t.Id}",r.Headers.Location?.OriginalString);}
    [Fact] public async Task Invalid_titles_cannot_create_data() {using var s=new ApiFixture();using var c=await s.Login();foreach(var title in new[]{" ",new string('x',121)})Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsJsonAsync("/api/work-items",new CreateInput(title))).StatusCode);Assert.Empty((await c.GetFromJsonAsync<ItemDto[]>("/api/work-items"))!);}
    [Fact] public async Task Unknown_status_cannot_create_data() {using var s=new ApiFixture();using var c=await s.Login();Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsJsonAsync("/api/work-items",new CreateInput("A","Unknown"))).StatusCode);Assert.Empty((await c.GetFromJsonAsync<ItemDto[]>("/api/work-items"))!);}
    [Fact] public async Task Filter_preserves_all_items() {using var s=new ApiFixture();using var c=await s.Login();var a=await ApiFixture.Add(c,"Pending");var b=await ApiFixture.Add(c,"Started","InProgress");var d=await ApiFixture.Add(c,"Finished","Done");Assert.Equal([a],(await c.GetFromJsonAsync<ItemDto[]>("/api/work-items?status=Todo"))!);Assert.Equal([b],(await c.GetFromJsonAsync<ItemDto[]>("/api/work-items?status=InProgress"))!);Assert.Equal([d],(await c.GetFromJsonAsync<ItemDto[]>("/api/work-items?status=Done"))!);Assert.Equal(3,(await c.GetFromJsonAsync<ItemDto[]>("/api/work-items"))!.Length);}
    [Fact] public async Task Invalid_filter_is_400() {using var s=new ApiFixture();using var c=await s.Login();Assert.Equal(HttpStatusCode.BadRequest,(await c.GetAsync("/api/work-items?status=Unknown")).StatusCode);}
    [Fact] public async Task Update_increments_version_and_returns_trimmed_state() {using var s=new ApiFixture();using var c=await s.Login();var a=await ApiFixture.Add(c);var r=await c.PutAsJsonAsync($"/api/work-items/{a.Id}",new UpdateInput("  Done  ","Done",1));Assert.Equal(HttpStatusCode.OK,r.StatusCode);Assert.Equal(a with{Title="Done",Status="Done",Version=2},await r.Content.ReadFromJsonAsync<ItemDto>());}
    [Fact] public async Task Stale_update_is_conflict_and_preserves_latest_item() {using var s=new ApiFixture();using var c=await s.Login();var a=await ApiFixture.Add(c);await c.PutAsJsonAsync($"/api/work-items/{a.Id}",new UpdateInput("New","InProgress",1));Assert.Equal(HttpStatusCode.Conflict,(await c.PutAsJsonAsync($"/api/work-items/{a.Id}",new UpdateInput("Stale","Done",1))).StatusCode);Assert.Equal(a with{Title="New",Status="InProgress",Version=2},(await c.GetFromJsonAsync<ItemDto[]>("/api/work-items"))!.Single());}
    [Fact] public async Task Invalid_update_never_changes_version_or_title() {using var s=new ApiFixture();using var c=await s.Login();var a=await ApiFixture.Add(c);Assert.Equal(HttpStatusCode.BadRequest,(await c.PutAsJsonAsync($"/api/work-items/{a.Id}",new UpdateInput(" ","Done",1))).StatusCode);Assert.Equal(a,(await c.GetFromJsonAsync<ItemDto[]>("/api/work-items"))!.Single());}
    [Fact] public async Task Invalid_update_status_preserves_item() {using var s=new ApiFixture();using var c=await s.Login();var a=await ApiFixture.Add(c);Assert.Equal(HttpStatusCode.BadRequest,(await c.PutAsJsonAsync($"/api/work-items/{a.Id}",new UpdateInput("A","Unknown",1))).StatusCode);Assert.Equal(a,(await c.GetFromJsonAsync<ItemDto[]>("/api/work-items"))!.Single());}
    [Fact] public async Task Non_positive_expected_version_is_400() {using var s=new ApiFixture();using var c=await s.Login();var a=await ApiFixture.Add(c);Assert.Equal(HttpStatusCode.BadRequest,(await c.PutAsJsonAsync($"/api/work-items/{a.Id}",new UpdateInput("A","Todo",0))).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await c.DeleteAsync($"/api/work-items/{a.Id}?expectedVersion=0")).StatusCode);}
    [Fact] public async Task Stale_delete_is_conflict_without_mutation() {using var s=new ApiFixture();using var c=await s.Login();var a=await ApiFixture.Add(c);await c.PutAsJsonAsync($"/api/work-items/{a.Id}",new UpdateInput("New","Done",1));Assert.Equal(HttpStatusCode.Conflict,(await c.DeleteAsync($"/api/work-items/{a.Id}?expectedVersion=1")).StatusCode);Assert.Single((await c.GetFromJsonAsync<ItemDto[]>("/api/work-items"))!);}
    [Fact] public async Task Valid_delete_removes_item_and_repeat_is_404() {using var s=new ApiFixture();using var c=await s.Login();var a=await ApiFixture.Add(c);Assert.Equal(HttpStatusCode.NoContent,(await c.DeleteAsync($"/api/work-items/{a.Id}?expectedVersion=1")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await c.DeleteAsync($"/api/work-items/{a.Id}?expectedVersion=1")).StatusCode);Assert.Empty((await c.GetFromJsonAsync<ItemDto[]>("/api/work-items"))!);}
    [Fact] public async Task Foreign_ids_are_404_even_with_stale_version() {using var s=new ApiFixture();using var a=await s.Login();var t=await ApiFixture.Add(a);using var b=await s.Login("bob@example.test","Bob!234");Assert.Empty((await b.GetFromJsonAsync<ItemDto[]>("/api/work-items"))!);Assert.Equal(HttpStatusCode.NotFound,(await b.PutAsJsonAsync($"/api/work-items/{t.Id}",new UpdateInput("Stolen","Done",999))).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await b.DeleteAsync($"/api/work-items/{t.Id}?expectedVersion=999")).StatusCode);Assert.Equal(t,(await a.GetFromJsonAsync<ItemDto[]>("/api/work-items"))!.Single());}
    [Fact] public async Task Concurrent_updates_allow_exactly_one_version_winner() {using var s=new ApiFixture();using var c=await s.Login();var a=await ApiFixture.Add(c);var replies=await Task.WhenAll(c.PutAsJsonAsync($"/api/work-items/{a.Id}",new UpdateInput("First","Done",1)),c.PutAsJsonAsync($"/api/work-items/{a.Id}",new UpdateInput("Second","InProgress",1)));Assert.Equal(1,replies.Count(r=>r.StatusCode==HttpStatusCode.OK));Assert.Equal(1,replies.Count(r=>r.StatusCode==HttpStatusCode.Conflict));Assert.Equal(2,(await c.GetFromJsonAsync<ItemDto[]>("/api/work-items"))!.Single().Version);}
}
